  $('soundTool').onclick=()=>this.toggleSound();$('voiceTool').onclick=()=>this.toggleVoice();$('themeTool').onclick=()=>this.toggleTheme();$('fullscreenTool').onclick=()=>this.toggleFullscreen();if($('moreTool'))$('moreTool').onclick=()=>this.openMobileTools();
  $('modalClose').onclick=()=>this.closeModal();$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))this.closeModal()});
