 async toggleReserve(cardId,reserve){if(this.working.has('reserve'))return;this.working.add('reserve');try{this.apply(await this.req('/api/player/reserve',{method:'POST',body:JSON.stringify({cardId,reserve})}))}catch(e){this.toast(e.message);await this.refresh(false)}finally{this.working.delete('reserve')}}
 async renewOffers(){try{this.apply(await this.req('/api/player/renew-offers',{method:'POST',body:'{}'}))}catch(e){this.toast(e.message)}}
